자판기 프로그램 소드코드
#include <iostream>
using namespace std;
// 음료 자판기 프로그램을 클래스로 설계하고 객체를 선언하여 상품 선택과 출력, 거스름돈 출력하는 프로그램
// 
//자판기에 대한 클래스
//맴버 변수 : 상품 (6가지), 메뉴, 지불할 돈, 거스름 돈
//맴버 함수 : 행위 상품을 구매 : void purchase()
//자판기객체 클래스 선언 및 정의
class VendingMachine{
private:
	int menu, pay, change; //메뉴, 지불할돈, 거스름돈
public:
	//상품 개수를 지정
	static const int PRODUCT_SIZE = 6;
	string product[PRODUCT_SIZE];
	//0 콜라, 1 사이타, 2 커피, 3 껌, 4 과자, 5 초콜릿
	//자판기 객체 소멸자
	~VendingMachine() { cout << "자판기 객체 소멸" << endl; }
	//자판기 객체의 생성자
	VendingMachine() { }
	VendingMachine(int pay) {
		//생성자를 통하여 맴버변수 초기화
		this->pay = pay;
		menu = 7;
		change = 0;
		product[0] = {"콜라"};
		product[1] = { "사이다" };
		product[2] = { "커피" };
		product[3] = { "껌" };
		product[4] = { "과자" };
		product[5] = { "초콜릿" };
	}
	//배치된 상품을 출력하고 메뉴를 출력하여 상품을 선택하는 purchase() 맴버함수
	void purchase() {	
		cout << "  ************** 메뉴 ***********************************" << endl;
		cout << " 1.콜라 2.사이다 3.커피 4.껌 5.과자 6.초콜릿 7.종료" << endl;
		cout << " ********************************************************" << endl;
		cout << "메뉴 선택 : "; cin >> menu;
		//switch case문을 통하여 메뉴선택
		switch (menu) {
			case 1: selecteItem(menu-1); break;
			case 2: selecteItem(menu-1); break;
			case 3: selecteItem(menu-1); break;
			case 4: selecteItem(menu-1); break;
			case 5: selecteItem(menu-1); break;
			case 6: selecteItem(menu-1); break;
			case 7: cout << "7" << endl; break;
			default: cout << "자판기 입니다." << endl;
		}
	}
	//배치된 상품을 선택하면 선택된 메뉴에따라 상품이 선택되어 거스름돈이 계산되고 출력되는 맴버함수
	void selecteItem(int menu) {
		//콜라는 750원 사이다는 800원 커피는 1000원 껌은 500원 과자는 1100원으로 지정
		// menu = 0이면 콜라
		// menu = 1이면 사이다
		// menu = 2이면 커피
		// menu = 3이면 껌
		// menu = 4이면 과자
		// menu = 5이면 초콜릿
		//거스름돈이 지불할 금액보다 크면 선택된 상품에 대한 구매가 이루어지고 거스름돈이 계산
		if (change < pay) {
			if (menu == 0) {
				cout << "콜라 선택" << endl;
				change = pay - 750;
			}
			else if (menu == 1) {
				cout << "사이다 선택" << endl;
				change = pay - 800;
			}
			else if (menu == 2) {
				cout << "커피 선택" << endl;
				change = pay - 1000;
			}
			else if (menu == 3) {
				cout << "껌 선택" << endl;
				change = pay - 500;
			}
			else if (menu == 4) {
				cout << "과자 선택" << endl;
				change = pay - 1100;
			}
			else if (menu = 5) {
				cout << "초콜릿 선택" << endl;
				change = pay - 900;
			}
			cout << "거스름돈 : " << change << endl;
		}
		else {
			cout << "잔액부족" << endl;
		}
	}
};
int main() {
	int pay = 0;
	//금액을 입력받아서 pay 변수에 저장
	cout << "금액을 입력하시오" << endl;  cin >> pay;
	//객체생성과 동시에 pay 지불금액을 전달
	VendingMachine vm = VendingMachine(pay);
	//purchase() 함수를 호출하여 상품 구매 진행
	vm.purchase();
	return 0;
}
